import {positive,money,reconcileNfe,importInvoice} from './domain.mjs';
export const materialCategories=['Matéria-prima','Acessório','Componente'];
const text=(v,name)=>{if(typeof v!=='string'||!v.trim())throw Error(name+' é obrigatório');return v.trim()};
export function editMaterial(state,materialId,patch,actor){let m=state.materials.find(x=>x.id===materialId);if(!m)throw Error('Material não encontrado');actor=text(actor,'Responsável');let next={...m,code:text(patch.code,'Código'),description:text(patch.description,'Descrição'),buyUnit:text(patch.buyUnit,'Unidade de compra'),unit:text(patch.unit,'Unidade de consumo'),category:patch.category,supplier:patch.supplier,purchaseFactor:positive(patch.purchaseFactor,'Conversão',false)};if(!materialCategories.includes(next.category))throw Error('Categoria inválida');if(!state.suppliers.some(x=>x.id===next.supplier))throw Error('Escolha o fornecedor');if(state.materials.some(x=>x.id!==m.id&&x.code===next.code&&x.supplier===next.supplier))throw Error('Código já cadastrado para este fornecedor');let unitChanged=next.unit!==m.unit;if(unitChanged&&state.proposals.some(p=>p.materialId===m.id&&p.status==='pending'))throw Error('Decida os custos pendentes antes de alterar a unidade de consumo');let hasCost=patch.cost!==undefined&&String(patch.cost).trim()!=='';if(unitChanged&&!hasCost)throw Error('Informe o custo proposto na nova unidade de consumo');let cost=hasCost?positive(patch.cost,'Custo proposto'):null,old=structuredClone(m);if(unitChanged)next.cost=null;Object.assign(m,next);if(hasCost&&(unitChanged||m.cost===null||cost!==m.cost)){state.proposals.push({id:crypto.randomUUID(),materialId:m.id,old:old.cost,cost,status:'pending',at:new Date().toISOString().slice(0,10),unit:m.unit,source:'Edição do cadastro'})}state.audit.push({at:new Date().toISOString(),actor,action:'material-edited',materialId:m.id,before:old,after:structuredClone(m)});return m}
export function editSupplier(state,supplierId,patch,actor){let s=state.suppliers.find(x=>x.id===supplierId);if(!s)throw Error('Fornecedor não encontrado');let next={name:text(patch.name,'Nome'),document:text(patch.document,'Documento')};actor=text(actor,'Responsável');if(state.suppliers.some(x=>x.id!==s.id&&x.document===next.document))throw Error('Documento já cadastrado');let before=structuredClone(s);Object.assign(s,next);state.audit.push({at:new Date().toISOString(),actor,action:'supplier-edited',supplierId:s.id,before,after:structuredClone(s)});return s}
export function editInvoiceDraft(invoice,patches){let next=structuredClone(invoice);next.sourceItems??=structuredClone(invoice.items);next.sourceTotals??=structuredClone(invoice.totals);if(patches.length!==next.items.length)throw Error('Quantidade de itens divergente');next.items=next.items.map((x,i)=>{let p=patches[i],edited={...x,code:text(p.code,'Código do item'),description:text(p.description,'Descrição'),unit:text(p.unit,'Unidade de compra'),taxes:{...x.taxes}};for(let k of ['quantity','unitPrice','total','discount','freight','insurance','other'])edited[k]=positive(p[k],k,k!=='quantity');if(Math.abs(money(edited.quantity*edited.unitPrice)-money(edited.total))>.011)throw Error('Quantidade × preço unitário não confere com o total do item '+edited.code);for(let k of Object.keys(x.taxes||{}))if(p.taxes&&p.taxes[k]!==undefined)edited.taxes[k]=positive(p.taxes[k],'Imposto '+k);return edited});return reconcileNfe(next)}
export function reviseInvoice(state,purchaseId,invoice,settings,actor){actor=text(actor,'Responsável');let prior=state.purchases.find(p=>p.id===purchaseId);if(!prior?.approveWholeInvoice)throw Error('Nota XML não encontrada');if(invoice.key!==prior.key||money(invoice.total)!==money(prior.total))throw Error('Preserve a chave e o total original da nota');let next=structuredClone(state);let archived=next.proposals.filter(p=>p.purchaseId===purchaseId);archived.forEach(p=>{if(p.status==='pending')p.status='superseded'});next.purchases=next.purchases.filter(p=>p.id!==purchaseId);next.entries=next.entries.filter(e=>e.purchaseId!==purchaseId);let added=importInvoice(next,invoice,settings),newId=added.id;added.id=purchaseId;added.installments=structuredClone(prior.installments);for(let e of next.entries)if(e.purchaseId===newId)e.purchaseId=purchaseId;for(let p of next.proposals)if(p.purchaseId===newId)p.purchaseId=purchaseId;next.audit.push({at:new Date().toISOString(),actor,action:'invoice-edited',purchaseId,total:prior.total,before:structuredClone(prior.items),after:structuredClone(added.items)});Object.assign(state,next);return added}
